-- Each run inserts a new version only when the content changed, so published versions stay immutable.

do $seed$
declare eid uuid; c jsonb := $j${"schemaVersion":1,"id":"ego-check","title":"Who is in Control?","tagline":"Who's driving today: you, or your autopilot?","emoji":"🪞🚗","category":"reflection","description":"Ten everyday work moments, a few seconds each. Go with your first instinct, then look in a private mirror: are you behind the wheel, or are your reflexes driving? The group sees only an anonymous team score.","durationMin":12,"players":{"min":5,"max":80},"languages":["en"],"ageRating":"16+","facilitator":"optional","modes":["live","self","practice"],"defaultTiming":{"readSec":4,"answerSec":15},"reveal":"none","privacy":{"individualResults":true,"groupMinimum":5,"retainResponses":false},"scoring":{"kind":"behaviour","minAnsweredRatio":0.7},"results":[{"min":0,"max":25,"emoji":"🥳","title":"Cool, calm and in the driver's seat!","message":"Your autopilot is napping in the back seat. 😴 You're driving. Keep it up!","explanation":"Your answers show curiosity, humility and openness, even in moments that sting.","groupTitle":"Our team is cool, calm and in control!","groupMessage":"Our autopilots are napping. We choose how we react. 😴","tone":"great"},{"min":26,"max":50,"emoji":"😎","title":"You're mostly in control!","message":"Now and then your autopilot honks from the back seat. 📯 But you usually keep the wheel.","explanation":"Most of your reactions are open and collaborative. A few situations pull you towards defending or proving yourself, which is very human.","groupTitle":"We're mostly in control!","groupMessage":"A few honks from the back seat, but we keep the wheel. 📯","tone":"good"},{"min":51,"max":75,"emoji":"🦙","title":"The llama grabbed the wheel!","message":"In some moments your first reflex takes over the steering. Good news: llamas can be retrained.","explanation":"In several situations your first reflex protected your position or your credit. Noticing that is the hardest part, and you just did.","groupTitle":"The team llama grabbed the wheel!","groupMessage":"Our reflexes take over now and then. Good thing we're noticing. 🦙","tone":"watch"},{"min":76,"max":100,"emoji":"🏎️","title":"Autopilot on full throttle!","message":"Your quick reflexes are doing donuts in the parking lot. Time to grab the wheel back. 😄","explanation":"Today your quick reactions leaned towards defending, convincing or claiming credit. That says more about fast reflexes than about who you are, and reflexes can be retrained.","groupTitle":"Our autopilot is on full throttle!","groupMessage":"Our reflexes did a lot of the driving. Let's grab the wheel together. 🏎️","tone":"grow"}],"insights":{"themes":{"feedback":{"label":"Feedback","strength":"You stay open when your work is criticised.","growth":"Criticism can put you on the defensive quickly.","habit":"When feedback comes, ask one question before you answer.","challenge":"Ask one colleague: \"What's one thing I could do better?\" Just listen."},"credit":{"label":"Recognition","strength":"You can celebrate a colleague's win without keeping score.","growth":"Credit for shared work matters a lot to you.","habit":"Name one colleague's contribution out loud each week.","challenge":"Thank someone publicly for help they gave you this month."},"mistake":{"label":"Mistakes","strength":"You own your mistakes openly.","growth":"A mistake can make you look elsewhere first.","habit":"Say \"that one's on me\" early, then share the fix.","challenge":"Share one small mistake with your team and what you learned."},"disagree":{"label":"Disagreement","strength":"You get curious when people disagree with you.","growth":"Disagreement can switch you into convincing mode.","habit":"Before you reply, sum up their view in one sentence.","challenge":"In your next disagreement, ask \"What am I missing?\" first."},"idea":{"label":"Better ideas","strength":"You let the best idea win, whoever had it.","growth":"Letting go of your own idea is hard.","habit":"Ask \"which option is best for the client?\" instead of \"whose idea?\"","challenge":"Build on someone else's idea in your next meeting."},"change":{"label":"Change requests","strength":"You focus on the outcome, not on your pride.","growth":"Change requests can feel personal.","habit":"Ask \"what outcome do you need?\" before defending the work.","challenge":"When asked for a change, ask about the goal before you react."},"interrupt":{"label":"Interruptions","strength":"You hold your ground calmly when interrupted.","growth":"Interruptions can trigger a counter-attack.","habit":"Try \"Let me finish this thought, then I'm all ears.\"","challenge":"Notice one moment you want to interrupt — and wait three seconds."},"teamwin":{"label":"Team wins","strength":"Shared wins are enough for you.","growth":"Being left unmentioned can spoil a good moment.","habit":"Celebrate the team result first; raise credit 1:1 later if it matters.","challenge":"Congratulate the team on a win and leave yourself out of it."},"unknown":{"label":"Not knowing","strength":"You are comfortable saying \"I don't know\".","growth":"Not knowing can feel like losing face.","habit":"Practise \"I don't know yet — I'll find out.\"","challenge":"Say \"I don't know\" at least once tomorrow — and follow up."},"decision":{"label":"Team decisions","strength":"You commit once the team decides.","growth":"Letting go after a decision takes real effort.","habit":"Once a decision is made, write down one way you'll help it work.","challenge":"Help move forward one decision you didn't agree with."}},"defaultHabit":"Keep asking \"what am I missing?\" in meetings. It keeps you in the driver's seat.","defaultChallenge":"Ask one colleague how you could support them better this week."},"transitions":["Some reflexes just woke up… 👀","The mirror saw that. 🪞","Hands on the wheel, everyone! 🚗","Was that you or your autopilot? 🤔","Green light, keep going! 🚦","Somebody check the rear-view mirror. 😏","The llama is watching. 🦙","Seatbelts on, this one is spicy. 🌶️","Nobody saw your answer. Only you. 🤫","Finish line! 🏁"],"closing":{"questions":["When does my autopilot take the wheel?","How can I notice it earlier?","What can I do differently tomorrow?"],"message":"Reflexes are human. Just don't let them drive every meeting. 🚗💜"},"disclaimer":"A light-hearted reflection game, not a psychological assessment or a performance tool. Feelings never count against you, only reactions do.","creator":"Remotecoders","status":"published","rounds":[{"id":"main","activities":[{"id":"q1","prompt":"Your slide gets roasted in a meeting. First reaction?","theme":"feedback","type":"choice","options":[{"id":"a","text":"I launch a 12-slide counter-presentation. 🛡️","points":3},{"id":"b","text":"I smile, nod and quietly decide they have no taste.","points":2},{"id":"c","text":"Ouch. But I hear them out.","points":0},{"id":"d","text":"\"Fair! What would you change?\"","points":0}],"shuffle":true},{"id":"q2","prompt":"Your colleague gets a round of applause for the thing you helped build.","theme":"credit","type":"choice","options":[{"id":"a","text":"I replay it in my head all evening. 🎬","points":2},{"id":"b","text":"\"Fun fact: that was partly me!\" 🙋","points":3},{"id":"c","text":"I clap the loudest. 👏","points":0},{"id":"d","text":"A tiny \"hmm\", then I get a coffee.","points":0}],"shuffle":true},{"id":"q3","prompt":"Oops. You just spotted your own mistake.","theme":"mistake","type":"choice","options":[{"id":"a","text":"I raise my hand: \"My bad, fixing it!\"","points":0},{"id":"b","text":"I first check who else touched it. 🕵️","points":2},{"id":"c","text":"I fix it at 11 pm and tell nobody. 🥷","points":3},{"id":"d","text":"I explain what happened and own it.","points":0}],"shuffle":true},{"id":"q4","prompt":"Someone disagrees with your brilliant idea.","theme":"disagree","type":"choice","options":[{"id":"a","text":"I explain it again. Louder. 📢","points":2},{"id":"b","text":"\"Interesting! What do you see that I don't?\"","points":0},{"id":"c","text":"Inner sigh, outer open mind.","points":0},{"id":"d","text":"Clearly they just didn't get it yet.","points":3}],"shuffle":true},{"id":"q5","prompt":"A colleague suggests an approach that is… actually better than yours.","theme":"idea","type":"choice","options":[{"id":"a","text":"Switch! Best idea wins. 🏆","points":0},{"id":"b","text":"Give me a moment to grieve, then I'm in.","points":0},{"id":"c","text":"I defend my idea like it's my firstborn.","points":3},{"id":"d","text":"\"Great!\" (I'm already hunting for its flaws.) 🔍","points":2}],"shuffle":true},{"id":"q6","prompt":"Your manager wants changes to something you polished for days.","theme":"change","type":"choice","options":[{"id":"a","text":"I take it personally. 💔","points":2},{"id":"b","text":"\"Sure, what outcome do you need?\"","points":0},{"id":"c","text":"I say \"but…\" before they finish the sentence.","points":3},{"id":"d","text":"Disappointed, but I hear them out.","points":0}],"shuffle":true},{"id":"q7","prompt":"You get interrupted mid-sentence. Again.","theme":"interrupt","type":"choice","options":[{"id":"a","text":"My eyebrows do all the talking. 🤨","points":2},{"id":"b","text":"\"Let me finish this thought, then I'm all ears.\"","points":0},{"id":"c","text":"I interrupt them back. Fair is fair. 🎤","points":3},{"id":"d","text":"I let them finish, then calmly pick up my thread.","points":0}],"shuffle":true},{"id":"q8","prompt":"The team wins big, and nobody mentions your part.","theme":"teamwin","type":"choice","options":[{"id":"a","text":"The cake suddenly tastes worse. 🍰","points":2},{"id":"b","text":"A win is a win. Party time! 🎉","points":0},{"id":"c","text":"I send a recap email listing my contributions.","points":3},{"id":"d","text":"I notice, shrug and enjoy the cake.","points":0}],"shuffle":true},{"id":"q9","prompt":"Someone asks you something you have no idea about.","theme":"unknown","type":"choice","options":[{"id":"a","text":"\"No idea, but I'll find out!\"","points":0},{"id":"b","text":"I answer confidently anyway. Sounds legit. 🤓","points":3},{"id":"c","text":"\"Let's ask someone who really knows.\"","points":0},{"id":"d","text":"I change the subject to the weather. ☀️","points":2}],"shuffle":true},{"id":"q10","prompt":"You're 100% sure you're right, but the team picks another direction.","theme":"decision","type":"choice","options":[{"id":"a","text":"I keep arguing until the meeting ends. ⏰","points":3},{"id":"b","text":"I share my concerns, then fully back it.","points":0},{"id":"c","text":"I go along, but I'm secretly waiting for \"I told you so\".","points":1},{"id":"d","text":"I stay curious and help make it work.","points":0}],"shuffle":true}]}]}$j$::jsonb; last jsonb;
begin
  insert into pp.experiences(slug, title, visibility, status, built_in) values ('ego-check', c->>'title', 'public', 'published', true)
    on conflict (slug) do update set title = excluded.title, updated_at = now() returning id into eid;
  select content into last from pp.experience_versions where experience_id = eid order by version desc limit 1;
  if last is distinct from c then
    insert into pp.experience_versions(experience_id, version, content, schema_version)
      values (eid, coalesce((select max(version) from pp.experience_versions where experience_id = eid), 0) + 1, c, 1);
  end if;
end $seed$;

