xt":"Know every programming language","emoji":"🧠"},{"id":"b","text":"Speak every human language","emoji":"🗣️"}]},{"id":"w6","prompt":"Would you rather…","type":"poll","options":[{"id":"a","text":"Camera always on","emoji":"📹"},{"id":"b","text":"Always be the one who forgot to unmute","emoji":"🔇"}]},{"id":"w7","prompt":"Would you rather…","type":"poll","options":[{"id":"a","text":"Four-day week, longer days","emoji":"🏖️"},{"id":"b","text":"Five-day week, short days","emoji":"🕐"}]},{"id":"w8","prompt":"Would you rather…","type":"poll","options":[{"id":"a","text":"Slow Wi-Fi forever","emoji":"🐌"},{"id":"b","text":"Laptop battery that lasts one hour","emoji":"🔋"}]},{"id":"w9","prompt":"Would you rather…","type":"poll","options":[{"id":"a","text":"Have a mentor for life","emoji":"🦸"},{"id":"b","text":"Mentor someone for life","emoji":"🧭"}]},{"id":"w10","prompt":"Would you rather…","type":"poll","options":[{"id":"a","text":"Pick the team lunch forever","emoji":"🍕"},{"id":"b","text":"Pick the office playlist forever","emoji":"🎵"}]}]}]}$j$::jsonb; last jsonb;
