do $seed$
declare eid uuid; c jsonb := $j${"schemaVersion":1,"id":"ego-check-de","title":"Wer hat das Steuer?","tagline":"Wer fährt heute: du oder dein Autopilot?","emoji":"🪞🚗","category":"reflection","description":"Zehn Alltagsmomente bei der Arbeit, je ein paar Sekunden. Geh mit deinem ersten Impuls und schau dann in einen privaten Spiegel: Sitzt du am Steuer, oder fahren deine Reflexe? Die Gruppe sieht nur einen anonymen Teamwert.","durationMin":12,"players":{"min":5,"max":80},"languages":["de"],"ageRating":"16+","facilitator":"optional","modes":["live","self","practice"],"defaultTiming":{"readSec":4,"answerSec":15},"reveal":"none","privacy":{"individualResults":true,"groupMinimum":5,"retainResponses":false},"scoring":{"kind":"behaviour","minAnsweredRatio":0.7},"results":[{"min":0,"max":25,"emoji":"🥳","title":"Cool, ruhig und am Steuer!","message":"Dein Autopilot macht ein Nickerchen auf dem Rücksitz. 😴 Du fährst. Weiter so!","explanation":"Deine Antworten zeigen Neugier, Bescheidenheit und Offenheit, auch in Momenten, die wehtun.","groupTitle":"Unser Team ist cool, ruhig und am Steuer!","groupMessage":"Unsere Autopiloten schlafen. Wir entscheiden, wie wir reagieren. 😴","tone":"great"},{"min":26,"max":50,"emoji":"😎","title":"Du hast meistens die Kontrolle!","message":"Ab und zu hupt dein Autopilot vom Rücksitz. 📯 Aber meistens behältst du das Steuer.","explanation":"Die meisten deiner Reaktionen sind offen und kooperativ. Einige Situationen ziehen dich ins Verteidigen oder Beweisen, was sehr menschlich ist.","groupTitle":"Wir haben meistens die Kontrolle!","groupMessage":"Ein paar Hupen vom Rücksitz, aber wir behalten das Steuer. 📯","tone":"good"},{"min":51,"max":75,"emoji":"🦙","title":"Das Lama hat das Steuer übernommen!","message":"In manchen Momenten übernimmt dein erster Reflex die Lenkung. Gute Nachricht: Lamas lassen sich umerziehen.","explanation":"In mehreren Situationen hat dein erster Reflex deine Position oder deine Anerkennung geschützt. Das zu bemerken ist der schwierigste Teil, und das hast du gerade getan.","groupTitle":"Das Team-Lama hat das Steuer übernommen!","groupMessage":"Unsere Reflexe übernehmen ab und zu. Gut, dass wir es merken. 🦙","tone":"watch"},{"min":76,"max":100,"emoji":"🏎️","title":"Autopilot mit Vollgas!","message":"Deine schnellen Reflexe drehen Donuts auf dem Parkplatz. Zeit, das Steuer zurückzuholen. 😄","explanation":"Heute haben deine schnellen Reaktionen eher verteidigt, überzeugt oder Anerkennung beansprucht. Das sagt mehr über schnelle Reflexe als darüber, wer du bist, und Reflexe kann man trainieren.","groupTitle":"Unser Autopilot fährt mit Vollgas!","groupMessage":"Unsere Reflexe sind viel gefahren. Holen wir uns das Steuer gemeinsam zurück. 🏎️","tone":"grow"}],"insights":{"themes":{"feedback":{"label":"Feedback","strength":"Du bleibst offen, wenn deine Arbeit kritisiert wird.","growth":"Kritik bringt dich schnell in die Verteidigung.","habit":"Wenn Feedback kommt, stell zuerst eine Frage, bevor du antwortest.","challenge":"Frag jemanden: «Was könnte ich besser machen?» Und hör einfach zu."},"credit":{"label":"Anerkennung","strength":"Du kannst den Erfolg anderer feiern, ohne mitzuzählen.","growth":"Anerkennung für gemeinsame Arbeit ist dir sehr wichtig.","habit":"Nenne jede Woche laut den Beitrag einer Kollegin oder eines Kollegen.","challenge":"Danke diesen Monat jemandem öffentlich für seine Hilfe."},"mistake":{"label":"Fehler","strength":"Du stehst offen zu deinen Fehlern.","growth":"Bei einem Fehler schaust du zuerst woanders hin.","habit":"Sag früh «das geht auf mich» und teile dann die Lösung.","challenge":"Teile einen kleinen Fehler mit deinem Team und was du daraus gelernt hast."},"disagree":{"label":"Widerspruch","strength":"Du wirst neugierig, wenn andere anderer Meinung sind.","growth":"Widerspruch schaltet dich in den Überzeugungsmodus.","habit":"Bevor du antwortest, fasse ihre Sicht in einem Satz zusammen.","challenge":"Frag bei der nächsten Meinungsverschiedenheit zuerst: «Was übersehe ich?»"},"idea":{"label":"Bessere Ideen","strength":"Bei dir gewinnt die beste Idee, egal von wem.","growth":"Die eigene Idee loszulassen fällt dir schwer.","habit":"Frag «welche Option ist die beste für den Kunden?» statt «wessen Idee?».","challenge":"Baue im nächsten Meeting auf der Idee von jemand anderem auf."},"change":{"label":"Änderungswünsche","strength":"Du konzentrierst dich auf das Ergebnis, nicht auf deinen Stolz.","growth":"Änderungswünsche fühlen sich schnell persönlich an.","habit":"Frag «welches Ergebnis brauchst du?», bevor du die Arbeit verteidigst.","challenge":"Frag bei einem Änderungswunsch zuerst nach dem Ziel, bevor du reagierst."},"interrupt":{"label":"Unterbrechungen","strength":"Du bleibst ruhig bei deinem Punkt, wenn du unterbrochen wirst.","growth":"Unterbrechungen können einen Gegenangriff auslösen.","habit":"Probier: «Lass mich den Gedanken beenden, dann bin ich ganz Ohr.»","challenge":"Bemerke einen Moment, in dem du unterbrechen willst, und warte drei Sekunden."},"teamwin":{"label":"Teamerfolge","strength":"Gemeinsame Erfolge genügen dir.","growth":"Nicht erwähnt zu werden kann einen schönen Moment trüben.","habit":"Feiere zuerst das Teamergebnis; sprich Anerkennung später unter vier Augen an, wenn es wichtig ist.","challenge":"Gratuliere dem Team zu einem Erfolg und lass dich selbst dabei weg."},"unknown":{"label":"Nicht wissen","strength":"Du sagst ohne Mühe «ich weiss es nicht».","growth":"Nicht zu wissen fühlt sich an wie Gesichtsverlust.","habit":"Übe: «Ich weiss es noch nicht, ich finde es heraus.»","challenge":"Sag morgen mindestens einmal «ich weiss es nicht», und bleib dran."},"decision":{"label":"Teamentscheide","strength":"Du ziehst mit, sobald das Team entschieden hat.","growth":"Nach einem Entscheid loszulassen kostet dich Kraft.","habit":"Schreib nach einem Entscheid auf, wie du hilfst, dass er funktioniert.","challenge":"Hilf einem Entscheid voran, mit dem du nicht einverstanden warst."}},"defaultHabit":"Frag im Meeting weiterhin: «Was übersehe ich?» So bleibst du am Steuer.","defaultChallenge":"Frag diese Woche eine Kollegin oder einen Kollegen, wie du sie besser unterstützen kannst."},"transitions":["Ein paar Reflexe sind gerade aufgewacht … 👀","Der Spiegel hat das gesehen. 🪞","Hände ans Steuer, alle! 🚗","Warst das du oder dein Autopilot? 🤔","Grünes Licht, weiter geht's! 🚦","Kurz in den Rückspiegel schauen. 😏","Das Lama schaut zu. 🦙","Anschnallen, die nächste ist scharf. 🌶️","Niemand hat deine Antwort gesehen. Nur du. 🤫","Ziellinie! 🏁"],"closing":{"questions":["Wann übernimmt mein Autopilot das Steuer?","Wie kann ich es früher bemerken?","Was kann ich morgen anders machen?"],"message":"Reflexe sind menschlich. Lass sie nur nicht jedes Meeting fahren. 🚗💜"},"disclaimer":"Ein augenzwinkerndes Reflexionsspiel, kein psychologischer Test und kein Leistungsinstrument. Gefühle zählen nie gegen dich, nur Reaktionen.","creator":"Remotecoders","status":"published","rounds":[{"id":"main","activities":[{"id":"q1","prompt":"Deine Folie wird im Meeting zerpflückt. Erste Reaktion?","theme":"feedback","type":"choice","options":[{"id":"a","text":"Ich starte eine Gegenpräsentation mit 12 Folien. 🛡️","points":3},{"id":"b","text":"Ich lächle, nicke und beschliesse still, dass sie keinen Geschmack haben.","points":2},{"id":"c","text":"Autsch. Aber ich höre zu.","points":0},{"id":"d","text":"«Fair! Was würdest du ändern?»","points":0}],"shuffle":true},{"id":"q2","prompt":"Eine Kollegin bekommt Applaus für etwas, das du mitgebaut hast.","theme":"credit","type":"choice","options":[{"id":"a","text":"Ich spiele die Szene den ganzen Abend im Kopf ab. 🎬","points":2},{"id":"b","text":"«Fun Fact: Das war zum Teil ich!» 🙋","points":3},{"id":"c","text":"Ich klatsche am lautesten. 👏","points":0},{"id":"d","text":"Ein kleines «hmm», dann hole ich mir einen Kaffee.","points":0}],"shuffle":true},{"id":"q3","prompt":"Hoppla. Du entdeckst gerade deinen eigenen Fehler.","theme":"mistake","type":"choice","options":[{"id":"a","text":"Ich hebe die Hand: «Mein Fehler, ich behebe ihn!»","points":0},{"id":"b","text":"Ich prüfe zuerst, wer sonst noch daran gearbeitet hat. 🕵️","points":2},{"id":"c","text":"Ich behebe ihn um 23 Uhr und sage niemandem etwas. 🥷","points":3},{"id":"d","text":"Ich erkläre, was passiert ist, und stehe dazu.","points":0}],"shuffle":true},{"id":"q4","prompt":"Jemand ist mit deiner brillanten Idee nicht einverstanden.","theme":"disagree","type":"choice","options":[{"id":"a","text":"Ich erkläre sie nochmals. Lauter. 📢","points":2},{"id":"b","text":"«Spannend! Was siehst du, das ich nicht sehe?»","points":0},{"id":"c","text":"Innerlich seufzen, äusserlich offen bleiben.","points":0},{"id":"d","text":"Die Person hat es offensichtlich noch nicht verstanden.","points":3}],"shuffle":true},{"id":"q5","prompt":"Ein Kollege schlägt einen Ansatz vor, der … tatsächlich besser ist als deiner.","theme":"idea","type":"choice","options":[{"id":"a","text":"Wechseln! Die beste Idee gewinnt. 🏆","points":0},{"id":"b","text":"Gib mir kurz Zeit zum Trauern, dann bin ich dabei.","points":0},{"id":"c","text":"Ich verteidige meine Idee wie mein Erstgeborenes.","points":3},{"id":"d","text":"«Super!» (Ich suche schon nach den Schwachstellen.) 🔍","points":2}],"shuffle":true},{"id":"q6","prompt":"Deine Chefin will Änderungen an etwas, das du tagelang poliert hast.","theme":"change","type":"choice","options":[{"id":"a","text":"Ich nehme es persönlich. 💔","points":2},{"id":"b","text":"«Klar, welches Ergebnis brauchst du?»","points":0},{"id":"c","text":"Ich sage «aber …», bevor sie den Satz beendet.","points":3},{"id":"d","text":"Enttäuscht, aber ich höre zu.","points":0}],"shuffle":true},{"id":"q7","prompt":"Du wirst mitten im Satz unterbrochen. Schon wieder.","theme":"interrupt","type":"choice","options":[{"id":"a","text":"Meine Augenbrauen übernehmen das Reden. 🤨","points":2},{"id":"b","text":"«Lass mich den Gedanken beenden, dann bin ich ganz Ohr.»","points":0},{"id":"c","text":"Ich unterbreche zurück. Fair ist fair. 🎤","points":3},{"id":"d","text":"Ich lasse ausreden und nehme dann ruhig meinen Faden wieder auf.","points":0}],"shuffle":true},{"id":"q8","prompt":"Das Team feiert einen grossen Erfolg, und niemand erwähnt deinen Beitrag.","theme":"teamwin","type":"choice","options":[{"id":"a","text":"Der Kuchen schmeckt plötzlich schlechter. 🍰","points":2},{"id":"b","text":"Erfolg ist Erfolg. Party! 🎉","points":0},{"id":"c","text":"Ich schicke ein Recap-Mail mit meinen Beiträgen.","points":3},{"id":"d","text":"Ich merke es, zucke mit den Schultern und geniesse den Kuchen.","points":0}],"shuffle":true},{"id":"q9","prompt":"Jemand fragt dich etwas, wovon du keine Ahnung hast.","theme":"unknown","type":"choice","options":[{"id":"a","text":"«Keine Ahnung, aber ich finde es heraus!»","points":0},{"id":"b","text":"Ich antworte trotzdem souverän. Klingt plausibel. 🤓","points":3},{"id":"c","text":"«Fragen wir jemanden, der es wirklich weiss.»","points":0},{"id":"d","text":"Ich wechsle das Thema zum Wetter. ☀️","points":2}],"shuffle":true},{"id":"q10","prompt":"Du bist dir 100 % sicher, aber das Team wählt eine andere Richtung.","theme":"decision","type":"choice","options":[{"id":"a","text":"Ich argumentiere weiter, bis das Meeting vorbei ist. ⏰","points":3},{"id":"b","text":"Ich sage meine Bedenken und ziehe dann voll mit.","points":0},{"id":"c","text":"Ich mache mit, warte aber heimlich auf mein «Hab ich doch gesagt».","points":1},{"id":"d","text":"Ich bleibe neugierig und helfe, dass es funktioniert.","points":0}],"shuffle":true}]}]}$j$::jsonb; last jsonb;
begin
  insert into pp.experiences(slug, title, visibility, status, built_in) values ('ego-check-de', c->>'title', 'public', 'published', true)
    on conflict (slug) do update set title = excluded.title, updated_at = now() returning id into eid;
  select content into last from pp.experience_versions where experience_id = eid order by version desc limit 1;
  if last is distinct from c then
    insert into pp.experience_versions(experience_id, version, content, schema_version)
      values (eid, coalesce((select max(version) from pp.experience_versions where experience_id = eid), 0) + 1, c, 1);
  end if;
end $seed$;

