declare eid uuid; c jsonb := $j${"schemaVersion":1,"id":"ego-check-fr","title":"Qui est aux commandes ?","tagline":"Qui conduit aujourd’hui : toi ou ton pilote automatique ?","emoji":"🪞🚗","category":"reflection","description":"Dix situations de travail du quotidien, quelques secondes chacune. Suis ton premier instinct, puis regarde-toi dans un miroir privé : es-tu au volant, ou tes réflexes conduisent-ils ? Le groupe ne voit qu’un score d’équipe anonyme.","durationMin":12,"players":{"min":5,"max":80},"languages":["fr"],"ageRating":"16+","facilitator":"optional","modes":["live","self","practice"],"defaultTiming":{"readSec":4,"answerSec":15},"reveal":"none","privacy":{"individualResults":true,"groupMinimum":5,"retainResponses":false},"scoring":{"kind":"behaviour","minAnsweredRatio":0.7},"results":[{"min":0,"max":25,"emoji":"🥳","title":"Cool, calme et au volant !","message":"Ton pilote automatique fait la sieste à l’arrière. 😴 C’est toi qui conduis. Continue comme ça !","explanation":"Tes réponses montrent de la curiosité, de l’humilité et de l’ouverture, même dans les moments qui piquent.","groupTitle":"Notre équipe est cool, calme et aux commandes !","groupMessage":"Nos pilotes automatiques font la sieste. Nous choisissons comment réagir. 😴","tone":"great"},{"min":26,"max":50,"emoji":"😎","title":"Tu gardes presque toujours le contrôle !","message":"De temps en temps, ton pilote automatique klaxonne depuis l’arrière. 📯 Mais tu gardes en général le volant.","explanation":"La plupart de tes réactions sont ouvertes et coopératives. Quelques situations te poussent à te défendre ou à faire tes preuves, ce qui est très humain.","groupTitle":"Nous gardons presque toujours le contrôle !","groupMessage":"Quelques coups de klaxon à l’arrière, mais nous gardons le volant. 📯","tone":"good"},{"min":51,"max":75,"emoji":"🦙","title":"Le lama a pris le volant !","message":"Dans certains moments, ton premier réflexe prend la direction. Bonne nouvelle : les lamas se rééduquent.","explanation":"Dans plusieurs situations, ton premier réflexe a protégé ta position ou ta reconnaissance. Le remarquer est le plus difficile, et tu viens de le faire.","groupTitle":"Le lama de l’équipe a pris le volant !","groupMessage":"Nos réflexes prennent parfois le dessus. Heureusement qu’on le remarque. 🦙","tone":"watch"},{"min":76,"max":100,"emoji":"🏎️","title":"Pilote automatique à fond !","message":"Tes réflexes rapides font des dérapages sur le parking. Il est temps de reprendre le volant. 😄","explanation":"Aujourd’hui, tes réactions rapides ont plutôt défendu, convaincu ou revendiqué le mérite. Cela en dit plus sur des réflexes rapides que sur qui tu es, et les réflexes s’entraînent.","groupTitle":"Notre pilote automatique est à fond !","groupMessage":"Nos réflexes ont beaucoup conduit. Reprenons le volant ensemble. 🏎️","tone":"grow"}],"insights":{"themes":{"feedback":{"label":"Feedback","strength":"Tu restes ouvert quand ton travail est critiqué.","growth":"La critique te met vite sur la défensive.","habit":"Quand un feedback arrive, pose une question avant de répondre.","challenge":"Demande à un collègue : « Que pourrais-je mieux faire ? » Et écoute simplement."},"credit":{"label":"Reconnaissance","strength":"Tu sais célébrer la réussite d’un collègue sans compter les points.","growth":"La reconnaissance pour un travail commun compte beaucoup pour toi.","habit":"Cite chaque semaine à voix haute la contribution d’un collègue.","challenge":"Remercie publiquement quelqu’un pour son aide ce mois-ci."},"mistake":{"label":"Erreurs","strength":"Tu assumes ouvertement tes erreurs.","growth":"Face à une erreur, tu regardes d’abord ailleurs.","habit":"Dis tôt « c’est pour moi », puis partage la solution.","challenge":"Partage une petite erreur avec ton équipe et ce que tu en as appris."},"disagree":{"label":"Désaccord","strength":"Tu deviens curieux quand on n’est pas d’accord avec toi.","growth":"Le désaccord te fait passer en mode « convaincre ».","habit":"Avant de répondre, résume leur point de vue en une phrase.","challenge":"Lors du prochain désaccord, demande d’abord : « Qu’est-ce que je rate ? »"},"idea":{"label":"Meilleures idées","strength":"Tu laisses gagner la meilleure idée, peu importe d’où elle vient.","growth":"Lâcher ta propre idée est difficile.","habit":"Demande « quelle option est la meilleure pour le client ? » plutôt que « l’idée de qui ? ».","challenge":"Construis sur l’idée de quelqu’un d’autre lors de ta prochaine réunion."},"change":{"label":"Demandes de changement","strength":"Tu te concentres sur le résultat, pas sur ta fierté.","growth":"Les demandes de changement peuvent sembler personnelles.","habit":"Demande « de quel résultat as-tu besoin ? » avant de défendre ton travail.","challenge":"Face à une demande de changement, interroge l’objectif avant de réagir."},"interrupt":{"label":"Interruptions","strength":"Tu gardes calmement ta position quand on t’interrompt.","growth":"Les interruptions peuvent déclencher une contre-attaque.","habit":"Essaie : « Laisse-moi finir cette idée, ensuite je t’écoute. »","challenge":"Repère un moment où tu veux interrompre, et attends trois secondes."},"teamwin":{"label":"Victoires d’équipe","strength":"Les succès partagés te suffisent.","growth":"Ne pas être mentionné peut gâcher un beau moment.","habit":"Célèbre d’abord le résultat de l’équipe ; parle de reconnaissance plus tard en tête-à-tête si c’est important.","challenge":"Félicite l’équipe pour une réussite sans te mettre en avant."},"unknown":{"label":"Ne pas savoir","strength":"Tu dis facilement « je ne sais pas ».","growth":"Ne pas savoir peut donner l’impression de perdre la face.","habit":"Entraîne-toi : « Je ne sais pas encore, je vais trouver. »","challenge":"Dis « je ne sais pas » au moins une fois demain, et fais le suivi."},"decision":{"label":"Décisions d’équipe","strength":"Tu t’engages dès que l’équipe a décidé.","growth":"Lâcher prise après une décision te demande un vrai effort.","habit":"Une fois la décision prise, note une façon d’aider à ce qu’elle réussisse.","challenge":"Aide à faire avancer une décision avec laquelle tu n’étais pas d’accord."}},"defaultHabit":"Continue à demander « qu’est-ce que je rate ? » en réunion. Ça te garde au volant.","defaultChallenge":"Demande cette semaine à un collègue comment tu pourrais mieux le soutenir."},"transitions":["Quelques réflexes viennent de se réveiller… 👀","Le miroir a tout vu. 🪞","Les mains sur le volant, tout le monde ! 🚗","C’était toi ou ton pilote automatique ? 🤔","Feu vert, on continue ! 🚦","Un petit coup d’œil dans le rétroviseur. 😏","Le lama vous regarde. 🦙","Attachez vos ceintures, celle-ci est épicée. 🌶️","Personne n’a vu ta réponse. Seulement toi. 🤫","Ligne d’arrivée ! 🏁"],"closing":{"questions":["Quand mon pilote automatique prend-il le volant ?","Comment le remarquer plus tôt ?","Que puis-je faire autrement demain ?"],"message":"Les réflexes sont humains. Ne les laisse simplement pas conduire chaque réunion. 🚗💜"},"disclaimer":"Un jeu de réflexion avec humour, pas un test psychologique ni un outil d’évaluation. Les émotions ne comptent jamais contre toi, seules les réactions comptent.","creator":"Remotecoders","status":"published","rounds":[{"id":"main","activities":[{"id":"q1","prompt":"Ta présentation se fait démolir en réunion. Première réaction ?","theme":"feedback","type":"choice","options":[{"id":"a","text":"Je lance une contre-présentation de 12 slides. 🛡️","points":3},{"id":"b","text":"Je souris, je hoche la tête et je décide en silence qu’ils n’ont aucun goût.","points":2},{"id":"c","text":"Aïe. Mais je les écoute.","points":0},{"id":"d","text":"« Juste ! Qu’est-ce que tu changerais ? »","points":0}],"shuffle":true},{"id":"q2","prompt":"Une collègue est applaudie pour un projet que tu as aidé à construire.","theme":"credit","type":"choice","options":[{"id":"a","text":"Je repasse la scène dans ma tête toute la soirée. 🎬","points":2},{"id":"b","text":"« Anecdote : c’était un peu moi ! » 🙋","points":3},{"id":"c","text":"J’applaudis le plus fort. 👏","points":0},{"id":"d","text":"Un petit « hmm », puis je vais chercher un café.","points":0}],"shuffle":true},{"id":"q3","prompt":"Oups. Tu viens de repérer ta propre erreur.","theme":"mistake","type":"choice","options":[{"id":"a","text":"Je lève la main : « Ma faute, je corrige ! »","points":0},{"id":"b","text":"Je vérifie d’abord qui d’autre y a touché. 🕵️","points":2},{"id":"c","text":"Je corrige à 23 h et je n’en parle à personne. 🥷","points":3},{"id":"d","text":"J’explique ce qui s’est passé et je l’assume.","points":0}],"shuffle":true},{"id":"q4","prompt":"Quelqu’un n’est pas d’accord avec ton idée brillante.","theme":"disagree","type":"choice","options":[{"id":"a","text":"Je la réexplique. Plus fort. 📢","points":2},{"id":"b","text":"« Intéressant ! Qu’est-ce que tu vois que je ne vois pas ? »","points":0},{"id":"c","text":"Soupir intérieur, esprit ouvert à l’extérieur.","points":0},{"id":"d","text":"Visiblement, il n’a pas encore compris.","points":3}],"shuffle":true},{"id":"q5","prompt":"Un collègue propose une approche… vraiment meilleure que la tienne.","theme":"idea","type":"choice","options":[{"id":"a","text":"On change ! La meilleure idée gagne. 🏆","points":0},{"id":"b","text":"Laisse-moi faire mon deuil une minute, puis je suis partant.","points":0},{"id":"c","text":"Je défends mon idée comme mon premier-né.","points":3},{"id":"d","text":"« Super ! » (Je cherche déjà ses failles.) 🔍","points":2}],"shuffle":true},{"id":"q6","prompt":"Ta responsable demande des changements sur un travail que tu as peaufiné pendant des jours.","theme":"change","type":"choice","options":[{"id":"a","text":"Je le prends personnellement. 💔","points":2},{"id":"b","text":"« Bien sûr, de quel résultat as-tu besoin ? »","points":0},{"id":"c","text":"Je dis « mais… » avant qu’elle finisse sa phrase.","points":3},{"id":"d","text":"Déçu, mais j’écoute.","points":0}],"shuffle":true},{"id":"q7","prompt":"On te coupe la parole en pleine phrase. Encore.","theme":"interrupt","type":"choice","options":[{"id":"a","text":"Mes sourcils parlent pour moi. 🤨","points":2},{"id":"b","text":"« Laisse-moi finir cette idée, ensuite je t’écoute. »","points":0},{"id":"c","text":"Je lui coupe la parole à mon tour. Chacun son tour. 🎤","points":3},{"id":"d","text":"Je le laisse finir, puis je reprends calmement mon fil.","points":0}],"shuffle":true},{"id":"q8","prompt":"L’équipe remporte un grand succès, et personne ne mentionne ta contribution.","theme":"teamwin","type":"choice","options":[{"id":"a","text":"Le gâteau a soudain moins bon goût. 🍰","points":2},{"id":"b","text":"Une victoire est une victoire. Place à la fête ! 🎉","points":0},{"id":"c","text":"J’envoie un récapitulatif par e-mail avec mes contributions.","points":3},{"id":"d","text":"Je le remarque, je hausse les épaules et je savoure le gâteau.","points":0}],"shuffle":true},{"id":"q9","prompt":"On te pose une question dont tu n’as aucune idée.","theme":"unknown","type":"choice","options":[{"id":"a","text":"« Aucune idée, mais je vais trouver ! »","points":0},{"id":"b","text":"Je réponds avec assurance quand même. Ça a l’air crédible. 🤓","points":3},{"id":"c","text":"« Demandons à quelqu’un qui sait vraiment. »","points":0},{"id":"d","text":"Je change de sujet et parle de la météo. ☀️","points":2}],"shuffle":true},{"id":"q10","prompt":"Tu es sûr à 100 % d’avoir raison, mais l’équipe choisit une autre direction.","theme":"decision","type":"choice","options":[{"id":"a","text":"Je continue à argumenter jusqu’à la fin de la réunion. ⏰","points":3},{"id":"b","text":"Je partage mes doutes, puis je soutiens pleinement la décision.","points":0},{"id":"c","text":"Je suis le mouvement, mais j’attends en secret mon « je vous l’avais dit ».","points":1},{"id":"d","text":"Je reste curieux et j’aide à ce que ça marche.","points":0}],"shuffle":true}]}]}$j$::jsonb; last jsonb;
